from pathlib import Path
import sys,json,os
R=Path(__file__).resolve().parents[3];E=Path(__file__).parent;sys.path.insert(0,str(R/'Code2Video/src'))
from biology_expert.providers import ModelGateway,parse_json
from biology_expert.contracts import write,digest
for line in Path('/autodl-tmp/code2biovideo/.env').read_text().splitlines():
 if line and not line.startswith('#') and '=' in line:
  k,v=line.split('=',1);os.environ[k]=v
g=ModelGateway(E/'logs',{'deepseek':1000000,'qwen':1000000});f=E/'candidates/mitosis';model=json.loads((f/'typed_result.json').read_text())['model']
prompt="""Plan a COMPLETE 8-second educational animation from the approved typed scientific model. Return JSON only {scene_id,typed_model_hash,objects:[{object_id,entity_semantic_id,scientific_identity:{name,kind,origin_id},scientific_properties:{},anchors:{center:{kind:'center'}},visual_representation:{format:'path|circle|ellipse',points:[[x,y,0],...],center:[x,y,0],radius:0.15,width:0.4,height:0.8,color:'#hex',label:'short name',label_offset:[x,y,0],visible:true}}],relations:[{semantic_id,type,source,target,source_anchor:'center',target_anchor:'center'}],events:[{event_id,process_semantic_id,action_category,participant_bindings:{role:'object_id or list'},start_trigger,end_trigger,start_time,end_time,state_before:{},state_after:{},relation_semantic_ids:[],caption:'short English caption'}],actions:[{object_id,start_time,end_time,from:[x,y,0],to:[x,y,0],visible_after:true}],duration:8,scientific_simplifications:[]}. This is a generic path/ellipse/object-motion plan, NO code. All entity/process IDs must come from actual model. Expand declared cardinalities into distinct persistent instances; do not duplicate parent pair and its same components as extra chromosomes. Post-separation daughter identity is the SAME two sister objects, preserve origin_id and record role change in properties; entity_semantic_id can refer to original persistent entity plus semantic_state_alias in properties. Use separate rods for chromatids, actual centromere/kinetochore components at their constrictions, two poles and editable connection lines. Avoid generic isolated labeled circles masquerading as the mechanism. Show initial off-equator duplicated chromosome, align center, then separate existing sisters to opposite poles after connection breakdown. Relations must track actual moving targets via runtime adapter; no static fake lines. Components and poles must be legible and labels not overlap. Main mechanism x[-5.8,5.8] y[-2.2,2.3], captions y=-3.1. Path points are scene coordinates, no closed fill. Set process independent start/end times. No random icon creation at anaphase. Do not claim the molecular cleavage mechanism is shown. Return concise compact JSON under6500 tokens."""
old=json.loads((f/'scene_graph.json').read_text())
prompt+=' REPAIR CURRENT PLAN: do not create separate daughter_chromatid_A/B objects. Same sister objects must travel to poles with semantic_state_alias daughter state; use only original entity semantic refs. No duplicate whole-chromosome ellipse over its components: omit dup_chromosome as separately visible shape, represent parent via membership properties. Initial pair starts at x=-1.5,y=0 then moves to x=0 by t=2.5; sisters centered x=-.18,+.18 y=0 at metaphase, then move x=-3,+3 by t=7.5. Kinetochores follow each sister center; poles fixed x=-5,+5. Microtubules drawn as dynamic relations from poles to kinetochores (generic relation endpoints, not move line center). Label sisterA DOWN, sisterB UP, kinetochores no label to reduce crowding; use full visual label_offset [0,-1.3,0] and [0,1.3,0]. Avoid multiple entities sharing an origin and appearing simultaneously. Fix previous wrong plan where sisters stopped and separate daughter copies moved. Include connection definitions even if not every visual line maps a biochemical predicate; original model relation refs must stay valid. Return complete compact plan.'
scene=parse_json(g.request('deepseek','typed_scene_visual_plan',prompt+json.dumps({'model':model,'model_hash':digest(model),'previous_scene':old})))
assert scene['typed_model_hash']==digest(model)
entity_ids={e['semantic_id'] for e in model['entities']};process_ids={p['process_semantic_id'] for p in model['processes']}
assert all(o['entity_semantic_id'] in entity_ids for o in scene['objects']);assert all(e['process_semantic_id'] in process_ids for e in scene['events'])
write(f/'scene_graph_before_visual_repair.json',json.loads((f/'scene_graph.json').read_text()));write(f/'scene_graph.json',scene)
print('planned',len(scene['objects']),len(scene['actions']))
